PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,whatsapp TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('owner','manager','moderator','user')),financial INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active',pin_hash TEXT,created_at INTEGER NOT NULL,trial_until INTEGER NOT NULL,entitlement_until INTEGER NOT NULL DEFAULT 0,referrer_id INTEGER REFERENCES users(id),referral_paid INTEGER NOT NULL DEFAULT 0,assigned_to INTEGER REFERENCES users(id),consent_at INTEGER NOT NULL,last_active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS wallets (user_id INTEGER PRIMARY KEY,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0));
INSERT OR IGNORE INTO wallets(user_id,balance) VALUES(0,1000000000000);
CREATE TABLE IF NOT EXISTS ledger (id TEXT PRIMARY KEY,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),kind TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,reference TEXT UNIQUE);
CREATE TRIGGER IF NOT EXISTS ledger_move BEFORE INSERT ON ledger BEGIN
 SELECT CASE WHEN (SELECT balance FROM wallets WHERE user_id=NEW.from_id)<NEW.amount OR NOT EXISTS(SELECT 1 FROM wallets WHERE user_id=NEW.from_id) OR NOT EXISTS(SELECT 1 FROM wallets WHERE user_id=NEW.to_id) OR NEW.from_id=NEW.to_id THEN RAISE(ABORT,'Insufficient balance or invalid recipient') END;
 UPDATE wallets SET balance=balance-NEW.amount WHERE user_id=NEW.from_id;
 UPDATE wallets SET balance=balance+NEW.amount WHERE user_id=NEW.to_id;
END;
CREATE TRIGGER IF NOT EXISTS registration_reward AFTER INSERT ON users BEGIN
 INSERT INTO wallets(user_id,balance) VALUES(NEW.id,0);
 INSERT INTO ledger(id,from_id,to_id,amount,kind,created_at,reference) VALUES('signup-'||NEW.id,0,NEW.id,100,'registration',NEW.created_at,'signup-'||NEW.id);
END;
CREATE TABLE IF NOT EXISTS auth_codes (id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,payload TEXT NOT NULL,purpose TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL,consumed INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL,verified_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reserved_names (name TEXT PRIMARY KEY,kind TEXT NOT NULL DEFAULT 'technical',reason TEXT NOT NULL DEFAULT 'خدمة تقنية',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sites (id TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),manager_id INTEGER REFERENCES users(id),draft TEXT NOT NULL DEFAULT '{}',draft_version INTEGER NOT NULL DEFAULT 0,published TEXT,published_version INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',lock_hash TEXT,lock_message TEXT NOT NULL DEFAULT '',searchable INTEGER NOT NULL DEFAULT 1,allow_contact INTEGER NOT NULL DEFAULT 1,branding INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,authorization TEXT);
CREATE TABLE IF NOT EXISTS names (name TEXT PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),site_id TEXT REFERENCES sites(id),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),user_id INTEGER NOT NULL,snapshot TEXT NOT NULL,draft_version INTEGER NOT NULL,base_version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',kind TEXT NOT NULL DEFAULT 'content',reviewer_id INTEGER,reason TEXT,created_at INTEGER NOT NULL,decided_at INTEGER);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY,owner_id INTEGER NOT NULL,site_id TEXT,purpose TEXT NOT NULL,bucket_key TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,public INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS services (key TEXT PRIMARY KEY,name_ar TEXT NOT NULL,name_en TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,premium INTEGER NOT NULL DEFAULT 1,policy TEXT NOT NULL DEFAULT '{"trial":true,"subscription":true,"grant":true,"points":true}');
CREATE TABLE IF NOT EXISTS user_services (user_id INTEGER NOT NULL,key TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'default',until_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),amount REAL NOT NULL CHECK(amount>0),days INTEGER NOT NULL CHECK(days>0),receipt_id TEXT REFERENCES media(id),status TEXT NOT NULL DEFAULT 'requested',notes TEXT NOT NULL DEFAULT '',referrer_id INTEGER,reviewer_id INTEGER,created_at INTEGER NOT NULL,approved_at INTEGER,reversed_at INTEGER);
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,payment_id TEXT UNIQUE,kind TEXT NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS redemptions (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,days INTEGER NOT NULL CHECK(days>0),created_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS redemption_effect AFTER INSERT ON redemptions BEGIN
 INSERT INTO ledger(id,from_id,to_id,amount,kind,created_at,reference) VALUES(NEW.id,NEW.user_id,0,NEW.days*100,'redemption',NEW.created_at,NEW.id);
 UPDATE users SET entitlement_until=MAX(entitlement_until,trial_until,NEW.created_at)+NEW.days*86400 WHERE id=NEW.user_id;
END;
CREATE TRIGGER IF NOT EXISTS payment_effect AFTER UPDATE OF status ON payments WHEN NEW.status='approved' AND OLD.status IN ('requested','submitted') BEGIN
 INSERT INTO subscriptions(id,user_id,payment_id,kind,start_at,end_at,created_at) SELECT NEW.id,NEW.user_id,NEW.id,'paid',MAX(entitlement_until,trial_until,NEW.approved_at),MAX(entitlement_until,trial_until,NEW.approved_at)+NEW.days*86400,NEW.approved_at FROM users WHERE id=NEW.user_id;
 UPDATE users SET entitlement_until=MAX(entitlement_until,trial_until,NEW.approved_at)+NEW.days*86400 WHERE id=NEW.user_id;
 INSERT INTO ledger(id,from_id,to_id,amount,kind,created_at,reference) SELECT 'referral-'||NEW.user_id,0,NEW.referrer_id,1000,'referral',NEW.approved_at,'referral-'||NEW.user_id WHERE NEW.referrer_id IS NOT NULL AND NEW.referrer_id!=NEW.user_id AND NOT EXISTS(SELECT 1 FROM ledger WHERE reference='referral-'||NEW.user_id);
 UPDATE users SET referral_paid=1 WHERE id=NEW.user_id;
END;
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',read_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS contact_requests (id TEXT PRIMARY KEY,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,decided_at INTEGER);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY,request_id TEXT UNIQUE,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',last_activity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),sender_id INTEGER NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS blocks (user_id INTEGER NOT NULL,blocked_id INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,blocked_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,conversation_id TEXT,reason TEXT NOT NULL,evidence TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reviewer_id INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY,name TEXT NOT NULL,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',accepted_at INTEGER,reviewer_id INTEGER,created_at INTEGER NOT NULL,decided_at INTEGER);
CREATE TABLE IF NOT EXISTS handovers (id TEXT PRIMARY KEY,site_id TEXT NOT NULL,target_email TEXT NOT NULL,creator_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',accepted_by INTEGER,created_at INTEGER NOT NULL,accepted_at INTEGER);
CREATE TABLE IF NOT EXISTS quick_links (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,payload TEXT NOT NULL,expires_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS analytics (id INTEGER PRIMARY KEY AUTOINCREMENT,site_id TEXT NOT NULL,event TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS radar_sources (id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT UNIQUE NOT NULL,category TEXT NOT NULL,region TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,last_fetched INTEGER,last_error TEXT);
CREATE TABLE IF NOT EXISTS radar_items (id TEXT PRIMARY KEY,title TEXT NOT NULL,url TEXT UNIQUE NOT NULL,source_id TEXT NOT NULL,category TEXT NOT NULL,region TEXT NOT NULL,published_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS content (slug TEXT PRIMARY KEY,title_ar TEXT NOT NULL,title_en TEXT NOT NULL,body_ar TEXT NOT NULL,body_en TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY,amount REAL NOT NULL,description TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER,action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deletion_requests (id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,reason TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reviews_status ON reviews(status,created_at);
CREATE INDEX IF NOT EXISTS idx_sites_user ON sites(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_ledger_from ON ledger(from_id,created_at);
CREATE INDEX IF NOT EXISTS idx_ledger_to ON ledger(to_id,created_at);
CREATE INDEX IF NOT EXISTS idx_messages_conv ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS idx_analytics_site ON analytics(site_id,created_at);
CREATE INDEX IF NOT EXISTS idx_radar_recent ON radar_items(published_at);
CREATE INDEX IF NOT EXISTS idx_auth_email ON auth_codes(email,purpose,created_at);
